class TFMGraphTreeNodeWorkflow extends TFMGraphTreeNode
{
    str				groupName;
    ResourceName	resName;
}

Method.Source:
public void draw(System.Drawing.Graphics _bmpDC, Map _treeNodes)
{
    TFMGraphRectInteractionWorkflow wRect = rect as TFMGraphRectInteractionWorkflow;
    rect.parmLowerColor(255<<24);
    rect.parmUpperColor(128 + 128 << 8 + 128 << 16 + 255<<24);
    rect.parmTextColor(255 + 255 << 8 + 255 << 16 + 255<<24);
    /*rect.parmLeft(rect.parmLeft() - rect.iWidth()*0.25);
    rect.parmRight(rect.parmRight() + rect.iWidth()*0.25);*/
    wRect.parmResourceName(resName);
    arrowGraphScale = 0;
    super(_bmpDC, _treeNodes);
}

public str parmGroupName(str _groupName = groupName)
{
    groupName = _groupName;

    return groupName;
}

public ResourceName parmResourceName(ResourceName _resName = ResName)
{
    resName = _resName;
    return resName;
}
